// Fully Unrolled 64-Bit Direct CLA using Gate Primitives
module cla64_flat_gate_primitives_delays (
    input  [63:0] a,
    input  [63:0] b,
    input         cin,
    output [63:0] sum,
    output        cout
);

  wire [63:0] p, g;
  wire [64:1] c;

  // Step 1: Propagate & Generate Signals
  genvar i;
  generate
    for (i = 0; i < 64; i = i + 1) begin : gen_pg
      xor #(2) (p[i], a[i], b[i]);
      and #(2) (g[i], a[i], b[i]);
    end
  endgenerate

