  assign t_1[0] = g[0];
  and #(2) g_and_1_0 (t_1[1], cin, p[0]);
  or #(2) g_or_1 (c[1], t_1[0], t_1[1]);

  // Carry c[2]
  wire [2:0] t_2;
  assign t_2[0] = g[1];
  and #(2) g_and_2_1 (t_2[1], g[0], p[1]);
